def add(key, name, family, steps, sources, *, enter=None, exit=None, features=None, params=None,
        horizon="20 bars maximum unless algorithm states otherwise", note="", outcome=None):
    instrument, data, timeframe, failures = FAMILY_DEFAULTS[family]
    refs = sources.split()
    known = {s["id"] for s in SOURCES}
    assert set(refs) <= known, (key, set(refs) - known)
    row = dict(id=key, name=name, family=family, instrument=instrument, required_data=data,
               timeframe=timeframe, algorithm_steps=steps.split(" | "), source_ids=refs,
               evidence_status=outcome or "research_hypothesis_not_reproduced",
               translation="Engineered test specification informed by listed sources; not an exact paper replication.",
               parameter_policy="Starting values are test seeds, not optimized or literature-proven parameters.",
               parameters=params or {}, entry=enter, exit=exit, snapshot_features=features or {},
               implementation_status="executable_snapshot_rule" if enter is not None else "specified_algorithm_requires_specialized_engine",
               position_sizing="For directional tests: risk <=0.5% of equity per position, gross <=100%, per-asset <=20%; no negative cash; recompute on actual equity. Specialized sleeves use the explicit algorithm and collateral model.",
               holding_limit=horizon, execution_contract="Use completed observations only. Earliest order is after data available_at; price from next executable quote/bar. Missing data is unavailable, never a neutral or zero signal.",
               cost_contract="Ledger every leg: fee_bps, half_spread_bps, slippage/impact, borrow, funding, gas, FX and collateral interest as applicable; do not net away intermediate inventory.",
               failure_modes=failures, failure_retention="Preserve rejected, losing, inconclusive and positive trials with identical metadata and reason codes.",
               validation="Freeze formula and trial id; chronological train/validation/untouched test; purge overlapping labels; log all variants; account for multiple selection; cash/BTC/equal-weight comparators; prospective paper evaluation.",
               notes=note)
    assert key not in {s["id"] for s in STRATEGIES}
    STRATEGIES.append(row)

# Numeric snapshots are explicitly computed from completed bars by the consumer.
def bar(key, name, family, enter, exit, features, steps, refs="TALIB TECH_POS TECH_NEG", params=None):
    add(key,name,family,steps,refs,enter=enter,exit=exit,features=features,params=params)

