bar("vol_scaled_tsm","Volatility-scaled time-series momentum","trend","momentum > 0 and volatility > 0","momentum <= 0",{"momentum":"close/lag(close,90)-1","volatility":"STD(log_returns,30)*sqrt(365)"},"Determine direction from 90-day trailing return | Scale target by min(1,0.20/annualized_vol) within asset caps | Rebalance daily",refs="TSM CRYPTO_MOM")
