bar("tema","Triple exponential trend","trend","fast > slow","fast <= slow",{"fast":"TEMA(close,20)","slow":"TEMA(close,80)"},"Compute triple exponential averages | Long above slow filter | Exit reverse ordering")
bar("trix","TRIX trend","trend","trix > 0","trix <= 0",{"trix":"TRIX(close,30)"},"Compute rate of triple-smoothed EMA | Long positive slope | Exit nonpositive slope")
bar("linear_slope","Rolling regression trend","trend","slope > 0 and r_squared > 0.5","slope <= 0",{"slope":"OLS slope of trailing log(close),30 bars","r_squared":"same trailing regression R squared"},"Fit trailing regression only | Long positive high-fit slope | Exit nonpositive slope")
bar("sar","Parabolic SAR trend","trend","close > sar","close <= sar",{"close":"close","sar":"SAR(high,low,accel=0.02,max=0.2)"},"Compute recursive SAR without future extremes | Long above stop | Exit below stop")
bar("ichimoku","Ichimoku cloud filter","trend","close > cloud_top and tenkan > kijun","close < kijun",{"close":"close","cloud_top":"max(known_at_t_senkou_a,known_at_t_senkou_b)","tenkan":"(MAX9(high)+MIN9(low))/2","kijun":"(MAX26(high)+MIN26(low))/2"},"Align chart shifts to actual known timestamps | Long above visible cloud with tenkan above kijun | Exit below kijun",params={"conversion":9,"base":26,"span":52})
bar("supertrend","ATR Supertrend","trend","close > trailing_band","close <= trailing_band",{"close":"close","trailing_band":"stateful Supertrend final lower band, ATR14 multiplier3"},"Initialize ATR and stateful bands | Enter on upward state transition | Exit on downward transition")
bar("multi_horizon_trend","Multi-horizon trend vote","trend","votes >= 2","votes < 2",{"votes":"sum(sign(SMA10-SMA50)>0, sign(SMA20-SMA100)>0, sign(ROC90)>0)"},"Vote across three frozen trend horizons | Long when at least two positive | Exit on loss of majority",refs="TSM CRYPTO_MOM")
bar("chandelier","Chandelier trailing trend","trend","close > entry_high","close < trailing_stop",{"close":"close","entry_high":"MAX(high,20) excluding current bar","trailing_stop":"highest high since entry minus 3*ATR14"},"Break above prior highs | Trail stop below post-entry high | Exit stop or maximum holding time")
bar("rsi_reversion","RSI oversold reversion","reversal","rsi < 30","rsi >= 50",{"rsi":"RSI(close,14)"},"Buy oversold RSI | Exit at neutral RSI | Enforce time stop, no averaging beyond caps")
bar("rsi2","Short-horizon RSI2 reversion","reversal","rsi2 < 5 and close > slow","rsi2 > 70 or close < slow",{"rsi2":"RSI(close,2)","close":"close","slow":"SMA(close,200)"},"Require larger positive trend | Enter short RSI extreme | Exit on rebound or trend failure")
bar("bollinger_revert","Bollinger band reversion","reversal","close < lower","close >= mean",{"close":"close","lower":"SMA20(close)-2*STD20(close)","mean":"SMA20(close)"},"Buy close below lower band | Exit at middle band | Track trend-break losses")
bar("zscore_revert","Rolling price z-score reversion","reversal","z < -2","z >= 0",{"z":"(close-SMA30(close))/STD30(close)"},"Standardize deviation from trailing mean | Buy below negative two sigma | Exit at mean")
bar("stochastic_revert","Stochastic oscillator reversion","reversal","k < 20 and k > d","k > 80 or k < d",{"k":"STOCH_K(14,3)","d":"STOCH_D(14,3,3)"},"Find oversold stochastic turning up | Long | Exit on overbought or bearish crossing")
bar("williams_r","Williams percent-R reversion","reversal","williams < -80","williams > -20",{"williams":"WILLR(high,low,close,14)"},"Buy deeply negative Williams-R | Exit on upper-zone recovery | Time-limit stalled positions")
bar("cci_revert","Commodity-channel reversion","reversal","cci < -100","cci >= 0",{"cci":"CCI(high,low,close,20)"},"Measure typical-price deviation | Buy low CCI | Exit at center")
bar("cmo_revert","Chande momentum reversion","reversal","cmo < -50","cmo >= 0",{"cmo":"CMO(close,14)"},"Buy downside momentum extreme | Exit when balance normalizes | Record trend-continuation failures")
bar("ultimate_revert","Ultimate oscillator reversion","reversal","uo < 30","uo >= 50",{"uo":"ULTOSC(high,low,close,7,14,28)"},"Combine buying pressure across horizons | Buy low oscillator | Exit on neutral recovery")
bar("vwap_revert","Rolling VWAP deviation reversion","reversal","z < -2 and trend_strength < 20","z >= 0 or trend_strength > 30",{"z":"(close-rolling_VWAP20)/STD20(close)","trend_strength":"ADX14"},"Use a fixed trailing volume-weighted reference, not future session volume | Buy deep deviation in weak trend | Exit reference or strong trend")
bar("gap_revert","Large opening-gap reversion","reversal","gap < -0.05 and spread_bps < 20","recovered >= 0.5",{"gap":"open/previous_close-1","spread_bps":"last executable spread","recovered":"(price-entry)/(previous_close-entry), require denominator>0"},"Detect actual exchange gap relative to prior close | Trade only after opening data observed | Exit halfway to reference or time stop")
bar("shock_reversal","Volatility shock exhaustion","reversal","return_z < -3 and volume_z > 2","return_z > 0",{"return_z":"last return divided by prior 30-bar std","volume_z":"volume z-score versus prior30"},"Detect downside shock and unusual volume | Enter following observation with capped risk | Exit recovery or time stop")
bar("streak_reversal","Consecutive down-bar reversal","reversal","down_streak >= 4 and adx < 20","up_streak >= 2",{"down_streak":"consecutive completed close declines","up_streak":"consecutive completed close rises","adx":"ADX14"},"Count declines in nontrending market | Buy after four | Exit after two rebounds or holding stop")
bar("donchian","Donchian channel breakout","breakout","close > prior_high","close < prior_low",{"close":"close","prior_high":"MAX(high,20) excluding current bar","prior_low":"MIN(low,10) excluding current bar"},"Compute previous channel | Buy breakout above channel | Exit below shorter downside channel")
bar("bollinger_breakout","Bollinger breakout continuation","breakout","close > upper and volume_ratio > 1.5","close < mean",{"close":"close","upper":"SMA20+2*STD20","mean":"SMA20","volume_ratio":"volume/mean(previous20 volumes)"},"Require upper-band breakout with volume | Long continuation | Exit mean failure")
bar("keltner_breakout","Keltner ATR-channel breakout","breakout","close > upper","close < center",{"close":"close","upper":"EMA20+2*ATR20","center":"EMA20"},"Build ATR envelope around EMA | Long upper break | Exit center crossing")
bar("squeeze","Volatility compression breakout","breakout","bandwidth_rank < 0.2 and close > prior_high","close < mean",{"bandwidth_rank":"rank of Bollinger bandwidth among prior100","close":"close","prior_high":"prior20 high","mean":"SMA20"},"Require compressed range | Wait for upward breakout | Exit mean crossing")
bar("atr_breakout","ATR-normalized range expansion","breakout","close > previous_close + 2 * atr and volume_ratio > 1.5","close < previous_close",{"close":"close","previous_close":"lag(close,1)","atr":"ATR14 from previous bar","volume_ratio":"volume/previous20 mean"},"Compare move with lagged ATR | Trade next quote after expansion | Exit failed expansion or time stop")
bar("opening_range","UTC opening-range breakout","breakout","price > opening_high and session_ready > 0","price < opening_low",{"price":"latest completed close","opening_high":"max high in 00:00-01:00 UTC fixed session","opening_low":"min low in same session","session_ready":"1 only after initial range complete"},"Define UTC session despite 24/7 market | Freeze first-hour range | Trade later upside breakout and exit downside break")
bar("inside_bar","Inside-bar breakout","breakout","inside > 0 and price > mother_high","price < mother_low",{"inside":"1 if prior bar entirely within its previous bar","price":"latest price after setup known","mother_high":"setup mother bar high","mother_low":"setup mother bar low"},"Identify inside bar from completed candles | Buy later mother-high break | Exit mother-low failure")
bar("failed_breakout","Failed-breakdown reclaim","breakout","swept_low > 0 and close > level","close < level",{"swept_low":"1 if completed low breaches previously fixed support","close":"close","level":"support fixed before sweep"},"Define support without future pivots | Observe sweep and close reclaim | Buy next executable price with stop below reclaimed level")
bar("obv","On-balance-volume confirmation","volume","obv > obv_mean and close > slow","obv <= obv_mean or close <= slow",{"obv":"OBV(close,volume)","obv_mean":"SMA20(OBV)","close":"close","slow":"SMA50(close)"},"Accumulate signed volume | Long only with price-trend confirmation | Exit either failed filter")
bar("ad_line","Accumulation-distribution confirmation","volume","ad > ad_mean and close > mean","ad < ad_mean",{"ad":"Chaikin AD(high,low,close,volume)","ad_mean":"SMA20(AD)","close":"close","mean":"SMA20(close)"},"Compute close-location volume flow | Buy aligned accumulation | Exit AD trend reversal")
bar("chaikin","Chaikin oscillator flow","volume","adosc > 0 and close > mean","adosc <= 0",{"adosc":"EMA3(AD)-EMA10(AD)","close":"close","mean":"SMA20(close)"},"Compute AD oscillator | Long positive flow and price confirmation | Exit negative flow")
bar("mfi","Money-flow-index reversal","volume","mfi < 20","mfi >= 60",{"mfi":"MFI(high,low,close,volume,14)"},"Measure price-weighted money flow | Buy low index | Exit recovered flow")
