 ("mlp","Feedforward neural trading model","Use a fixed lagged feature vector and matured label horizon | Fit MLP with chronological early stopping and multiple seeds logged | Trade calibrated expected net return and keep all failed seeds","ML_CLASS ML_COST"),
 ("lstm","LSTM sequence forecast","Construct trailing sequence windows with no future scaling | Train on past labels, purge overlapping future outcomes and freeze architecture | Translate out-of-sample prediction to capped exposure after costs; compare linear baselines","ML_CLASS FINRL PREBIT"),
 ("cnn_temporal","Temporal convolutional price/text model","Feed only trailing market and frozen-model text embeddings | Train causal/dilated CNN with past labels and chronological validation | Test incremental value against price-only and random-text ablations","PREBIT ML_CLASS"),
 ("transformer_sequence","Causal transformer forecast","Apply causal mask to trailing price/text sequences and train-only normalization | Fit on training period with frozen available model/data versions | Calibrate forecasts on past validation; trade only cost-surplus, not raw predicted price","PREBIT FINBERT ML_COST"),
 ("hmm_regime","Hidden-Markov regime selector","Fit HMM on past returns/volatility only | At decision use filtered state probabilities, never smoothed probabilities using future observations | Select preregistered trend/reversion/cash experts from filtered regime","REGIME"),
 ("garch_risk","GARCH volatility-targeted exposure","Fit GARCH(1,1) to prior returns with fixed refit calendar | Predict next conditional volatility | Scale an independent direction signal to target volatility and cap gross leverage","REGIME RISK_PORT"),
